          "trechos": [
            "Ea944db7efcc2cc3a:0:696",
            "Ea944db7efcc2cc3a:696:1393"
          ],
          "condicoes": [
            "no contexto das auditorias internas do FPSO Cidade de São Mateus",
            "como evidência de monitoramento e melhoria contínua do SGSO"
          ],
          "limites": [
            "o trecho não especifica quais lógicas, setpoints ou sistemas críticos estavam afetados",
